static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    // 输入形状
    auto xShape = context->GetInputShape(0)->GetOriginShape();
    auto wShape = context->GetInputShape(1)->GetOriginShape();
    // x: [M, K], weight: [N, K] (按PyTorch Linear约定: W形状[out_features, in_features])
    uint32_t M = static_cast<uint32_t>(xShape.GetDim(0));
    uint32_t K = static_cast<uint32_t>(xShape.GetDim(1));
    uint32_t N = static_cast<uint32_t>(wShape.GetDim(0));

    // 设定block维度
    const uint32_t BLOCK_DIM = 8;
    context->SetBlockDim(BLOCK_DIM);

    // 保存自定义tiling给kernel（用于行列分块）
    MatmulDropoutMeanSoftmaxCustomTilingData tiling;
    tiling.set_M(M);
    tiling.set_N(N);
    tiling.set_K(K);
    // 简单设置分块参数
    const uint32_t tileM = 1;
    const uint32_t tileN = 8;
    tiling.set_tileNumM(tileM);
    tiling.set_tileNumN(tileN);

    // 写入原始tiling缓冲
    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    // workspace
    size_t* ws = context->GetWorkspaceSizes(1);
    ws[0] = 0;
    return ge::GRAPH_SUCCESS;
}
}

